# SPDX-License-Identifier: MIT
"""A self-declared generated file is recorded by its exact path, and loses ties in search.

THE COMPLAINT. A repository whose generated API clients made up most of its symbols had those
clients crowd hand-written code out of search. `_search_rank` had no term for the CLASS of file a
symbol lives in, so a thousand generated `getUser*` methods outranked the one a person wrote.

DEPRIORITISED, NEVER HIDDEN. Hiding generated code would be absence reported as emptiness, and
1.2.0 went the other way on purpose: a generated file is worth NAMING with what produced it. So the
penalty is smaller than one name-token match — a generated symbol loses a TIE, but still wins on
strictly better evidence, and an exact-name search for it still puts it first.

THE TRAP THIS AVOIDS. `generated_files` is joined on BASENAME, a documented limit for CMake rows,
where the build file names `${CMAKE_CURRENT_BINARY_DIR}/error.c` and nothing better is available.
Reused naively for a banner, it would mark EVERY `index.ts` generated — and the one generated file
measured in mattermost-mobile is `app/utils/emoji/index.ts`. A banner row knows its exact path, so
it is matched on the exact path.

ONLY SELF-DECLARED FILES ARE PENALISED. A CMake output is the project's own build product, and
mbedtls Q4's answer IS the CMake-generated `error.c`; demoting it would hurt a held cluster.

@brief Tests that self-declared generated files are recorded exactly and rank below their peers.
@version 1
"""

from __future__ import annotations

import sqlite3
from pathlib import Path

from clew.cli import _build_argparser, _run_pipeline
from clew.query.corpus import generation_rule
from clew.query.symbols import search

_BANNER = "// This file is automatically generated via `make emojis`. Do not modify it manually.\n"


## @brief Build a repository holding one generated and one hand-written `index.ts`.
## @param tmp_path Pytest temporary directory.
## @return Path to the built index.
## @version 1
def _build(tmp_path: Path) -> Path:
    """@brief Build the fixture.
    @return Database path.
    @version 1
    """
    repo = tmp_path / "repo"
    (repo / "app/emoji").mkdir(parents=True)
    (repo / "app/emoji/index.ts").write_text(
        _BANNER + "export function lookupEmoji(code: string) { return code; }\n", encoding="utf-8"
    )
    (repo / "app/index.ts").write_text(
        "export function lookupUser(id: string) { return id; }\n", encoding="utf-8"
    )
    out = tmp_path / "clew.db"
    _run_pipeline(_build_argparser().parse_args(["--output", str(out), "--repo-root", str(repo)]))
    return out


## @brief The generated file is recorded, and only that file.
## @param tmp_path Pytest temporary directory.
## @return None.
## @version 1
def test_a_self_declared_file_is_recorded_by_exact_path_only(tmp_path: Path) -> None:
    """@brief The generated `index.ts` is generated; the hand-written one is not.
    @version 1
    """
    conn = sqlite3.connect(_build(tmp_path))
    rule = generation_rule(conn, "app/emoji/index.ts")
    assert rule is not None and rule.kind.startswith("self-declared"), rule
    assert generation_rule(conn, "app/index.ts") is None, (
        "a hand-written index.ts was reported generated because another file shares its basename"
    )


## @brief On equal match strength, the hand-written symbol ranks first.
## @param tmp_path Pytest temporary directory.
## @return None.
## @version 1
def test_a_generated_symbol_loses_a_tie(tmp_path: Path) -> None:
    """`lookup` matches both names identically — the same substring and token score — so the only
    difference between them is which file each lives in.

    @brief Generated ranks below hand-written on a tie.
    @version 1
    """
    names = [hit.name for hit in search(_build(tmp_path), "lookup")]
    assert names.index("lookupUser") < names.index("lookupEmoji"), names


## @brief A generated symbol is never hidden, and wins on strictly better evidence.
## @param tmp_path Pytest temporary directory.
## @return None.
## @version 1
def test_an_exact_search_for_a_generated_symbol_still_finds_it_first(tmp_path: Path) -> None:
    """@brief Deprioritised, not hidden.
    @version 1
    """
    names = [hit.name for hit in search(_build(tmp_path), "lookupEmoji")]
    assert names and names[0] == "lookupEmoji", names
